arguments.command:
cd /workspace && python3 -I - <<'EOF'
import json, glob, os, re, collections, statistics
# validation fail_debug analysis
files=sorted(glob.glob("validation_data/*.jsonl"), key=lambda p:int(os.path.basename(p).split('.')[0]))
def norm(s):
    if s is None: return None
    if not isinstance(s,str): s=json.dumps(s)
    return "\n".join(l.rstrip() for l in s.strip().splitlines())
tot=collections.Counter(); near=0; examples=[]
err_kinds=collections.Counter()
for f in files:
    for l in open(f):
        r=json.loads(l); fd=r.get('fail_debug')
        if not fd: continue
        err=fd.get('error'); res=fd.get('result')
        if err:
            k=str(err).split(':')[0][:60]
            err_kinds[k]+=1
            tot['error']+=1
        else:
            tot['wrong_answer_or_other']+=1
            # near-miss check: is output (as list) equal to expected split lines?
            exp=fd.get('expected'); out=fd.get('output')
            try:
                outl=json.loads(out) if isinstance(out,str) and out.startswith('[') else out
            except Exception:
                outl=out
            exp_lines=[x.rstrip() for x in (exp or '').strip().splitlines()] if isinstance(exp,str) else exp
            if isinstance(outl,list):
                out_lines=[str(x).rstrip() for x in outl]
                if out_lines==exp_lines:
                    near+=1
                    if len(examples)<5: examples.append((fd['problem_id'],fd['fail_index'],repr(exp)[:200],repr(out)[:200],fd.get('result')))
            elif isinstance(outl,str):
                if norm(outl)==norm(exp):
                    near+=1
                    if len(examples)<5: examples.append((fd['problem_id'],fd['fail_index'],repr(exp)[:200],repr(out)[:200],fd.get('result')))
print("totals:", tot, "near-miss (normalized equal):", near)
print("error kinds:", err_kinds.most_common(15))
for e in examples: print("NEAR:", e)
# result field values
resvals=collections.Counter()
for f in files:
    for l in open(f):
        r=json.loads(l); fd=r.get('fail_debug')
        if fd: resvals[repr(fd.get('result'))]+=1
print("result values:", resvals)
# Show 6 diverse wrong-answer examples (short)
shown=0
for l in open("validation_data/45.jsonl"):
    r=json.loads(l); fd=r.get('fail_debug')
    if fd and not fd.get('error') and shown<6:
        shown+=1
        print("----", fd['problem_id'], "n_pass/n_tests=%s/%s"%(fd['n_pass'],fd['n_tests']), "fail_index", fd['fail_index'], "result", fd['result'])
        print("  input:", repr(fd['input'])[:150]); print("  expected:", repr(fd['expected'])[:150]); print("  output:", repr(fd['output'])[:150])
EOF

