import json, re
import pyarrow.parquet as pq
rows={r['extra_info']['problem_id']:r for r in pq.read_table("taco_verl/train.parquet").to_pylist()}

def norm(s):
    lines=[l.rstrip() for l in s.replace('\r','').strip('\n').split('\n')]
    while lines and lines[-1]=='': lines.pop()
    return '\n'.join(lines).strip()

def ref_sort(inp):
    toks=inp.split()
    n=int(toks[0]); a=sorted(int(x) for x in toks[1:1+n])
    return '\n'.join(str(x) for x in a)

def is_prime(x):
    if x<2: return False
    i=2
    while i*i<=x:
        if x%i==0: return False
        i+=1
    return True
def ref_grid(inp):
    n=int(inp.split()[0])
    return str(sum(1 for i in range(n) for j in range(n) if is_prime(i+j)))

def ref_fib(inp):
    a,b,n=map(int,inp.split()[:3])
    f=[0,a,b]
    for i in range(3,n+1): f.append(f[-1]+f[-2])
    return str(f[n])

def ref_swapcase(inp):
    return inp.rstrip('\n').swapcase()

for pid,ref in [('train9825',ref_sort),('train2553',ref_grid),('train21025',ref_fib)]:
    r=rows[pid]; gt=json.loads(r['reward_model']['ground_truth'])
    ins=gt['inputs']; outs=[norm(o) for o in gt['outputs']]
    print("="*90); print(pid, "n_tests", len(ins))
    q=r['prompt'][0]['content']; print("[Q tail]", repr(q[-300:]))
    match=0; elsewhere=0
    for i,(x,o) in enumerate(zip(ins,outs)):
        try: mine=norm(ref(x))
        except Exception as e: mine=f"<ref error {e!r}>"
        ok = (mine==o)
