    for r in rows:
        q=question(r['prompt'][0]['content']); s=style(q); sty[s]+=1; nt[s].append(r['extra_info']['n_tests'])
        outs=[norm(o) for o in json.loads(r['reward_model']['ground_truth'])['outputs']]
        if len(outs)>=2 and len(set(outs))==1: degenerate+=1; deg_ids.append((r['extra_info']['problem_id'],len(outs),outs[0][:20]))
