    print(f"   degenerate (all outputs identical, >=2 tests): {degenerate}  e.g. {deg_ids[:6]}")

# harness-quirk exposure in rollouts and val
def analyze(files, label):
    recs=[json.loads(l) for f in files for l in open(f)]
    def has(pat, r): return re.search(pat, r['output']) is not None
    checks={
      "__name__ guard": r"__name__\s*==\s*['\"]__main__['\"]",
      "exit()/quit() call": r"(?<![\w.])(exit|quit)\s*\(",
      "sys.exit": r"sys\.exit\s*\(",
      "sys.stdin.buffer / os.read": r"sys\.stdin\.buffer|os\.read\(",
      "threading / setrecursionlimit": r"threading\.|setrecursionlimit",
      "multiple code blocks": None,
    }
    print(f"==== {label}: n={len(recs)} overall acc={statistics.mean(r['acc'] for r in recs):.3f}")
    for name,pat in checks.items():
        if pat is None:
            sel=[r for r in recs if len(re.findall(r"```(.*?)```", r['output'], re.S))>1]
        else:
            sel=[r for r in recs if has(pat,r)]
