    ks=sorted(by_step)
    print("   __name__ guard usage by step (first5 / last5):", [(k,by_step[k][1]) for k in ks[:5]], [(k,by_step[k][1]) for k in ks[-5:]])
analyze(sorted(glob.glob("rollout_data/*.jsonl")), "ROLLOUTS")
analyze(sorted(glob.glob("validation_data/*.jsonl")), "VALIDATION")
EOF

